import ru.sveta.tyanu.TorrentEngine;
import org.libtorrent4j.*;
import org.libtorrent4j.swig.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.BooleanSupplier;

/** Downloads only locally generated bytes between two native BitTorrent sessions. */
public class EngineIntegrationTest {
    static void check(boolean test,String message){if(!test)throw new AssertionError(message);System.out.println("PASS "+message);}
    static void waitFor(BooleanSupplier test,String message)throws Exception{
        long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(35);
        while(System.nanoTime()<end){if(test.getAsBoolean()){System.out.println("PASS "+message);return;}Thread.sleep(150);}
        throw new AssertionError("Timeout: "+message);
    }
    static TorrentHandle connect(TorrentEngine e,String hash,int port)throws Exception{
        java.lang.reflect.Field field=TorrentEngine.class.getDeclaredField("manager");field.setAccessible(true);
        SessionManager m=(SessionManager)field.get(e);m.addListener(new AlertListener(){public int[] types(){return null;} public void alert(org.libtorrent4j.alerts.Alert<?> a){if(a.getClass().getSimpleName().startsWith("Peer") || a instanceof org.libtorrent4j.alerts.ListenSucceededAlert)System.out.println("DL "+a.getClass().getSimpleName()+" "+a.message());}}); TorrentHandle handle=m.find(Sha1Hash.parseHex(hash));
        handle.swig().connect_peer(new TcpEndpoint("127.0.0.1",port).swig());return handle;
    }
    public static void main(String[] args)throws Exception{
        File root=new File(args[0]);root.mkdirs();File seedDir=new File(root,"seed");File bundle=new File(seedDir,"bundle");bundle.mkdirs();
        byte[] one=new byte[512*1024],two=new byte[256*1024];new Random(42).nextBytes(one);new Random(43).nextBytes(two);
        Files.write(new File(bundle,"keep.bin").toPath(),one);Files.write(new File(bundle,"skip.bin").toPath(),two);
        byte[] torrent=new TorrentBuilder().path(bundle).pieceSize(16384).generate().entry().bencode();
        TorrentInfo ti=new TorrentInfo(torrent);String hash=ti.infoHashes().getBest().toHex();
        SettingsPack settings=new SettingsPack();settings.setString(settings_pack.string_types.listen_interfaces.swigValue(),"127.0.0.1:38429");
        settings.setEnableDht(false);settings.setEnableLsd(false);settings.setBoolean(settings_pack.bool_types.enable_upnp.swigValue(),false);settings.setBoolean(settings_pack.bool_types.enable_natpmp.swigValue(),false);
        SessionManager seed=new SessionManager();seed.addListener(new AlertListener(){public int[] types(){return null;} public void alert(org.libtorrent4j.alerts.Alert<?> a){if(a instanceof org.libtorrent4j.alerts.PeerErrorAlert || a instanceof org.libtorrent4j.alerts.ListenFailedAlert || a instanceof org.libtorrent4j.alerts.TorrentErrorAlert)System.out.println("ALERT "+a.message());}});seed.start(new SessionParams(settings));
        SessionHandle seedSession=new SessionHandle(seed.swig());AddTorrentParams params=new AddTorrentParams();params.setTorrentInfo(ti);params.setSavePath(seedDir.getAbsolutePath());params.setFlags(TorrentFlags.SEED_MODE);
        ErrorCode ec=new ErrorCode(new error_code());TorrentHandle seedHandle=seedSession.addTorrent(params,ec);check(!ec.isError()&&seedHandle.isValid(),"native seed session starts");System.out.println("SEED listening "+seedSession.getListenPort()+" "+seedSession.isListening()+" state "+seedHandle.status(true).state()+" seed "+seedHandle.status(true).isSeeding());Thread.sleep(1000);
        TorrentEngine engine=null;
        try {
            File state=new File(root,"state"),dest=new File(root,"download");engine=new TorrentEngine(state,0,0);final TorrentEngine first=engine;
            check(first.addTorrent(torrent,dest,true,new boolean[]{true,false}).equals(hash),"torrent-file import accepts a file selection");
            check(first.snapshot().get(0).paused,"new paused torrent stays paused");
            try{first.addTorrent(torrent,dest,false,null);throw new AssertionError("duplicate accepted");}catch(IllegalArgumentException expected){System.out.println("PASS duplicate is rejected");}
            try{first.addMagnet("bad",dest,false);throw new AssertionError("invalid magnet accepted");}catch(IllegalArgumentException expected){System.out.println("PASS invalid magnet is rejected");}
            first.pause(hash,false);connect(first,hash,38429);System.out.println("STATE "+first.snapshot().get(0).state+" "+first.snapshot().get(0).error+" size "+first.snapshot().get(0).size);
            waitFor(()->first.snapshot().get(0).finished,"selected file downloads from local BitTorrent peer");
            check(Arrays.equals(one,Files.readAllBytes(new File(dest,"bundle/keep.bin").toPath())),"downloaded bytes match original");
            check(!first.content(hash).get(1).wanted,"excluded file stays excluded");
            first.pause(hash,true);first.checkpoint();first.close();engine=null;
            engine=new TorrentEngine(state,0,0);final TorrentEngine restored=engine;
            check(restored.snapshot().size()==1&&restored.snapshot().get(0).paused,"pause survives engine restart");
            check(!restored.content(hash).get(1).wanted,"file selection survives engine restart");
            restored.remove(hash);check(restored.snapshot().isEmpty(),"remove clears torrent list");
            check(new File(dest,"bundle/keep.bin").isFile(),"remove keeps downloaded files");
            String magnet=seedHandle.makeMagnetUri();String magnetHash=restored.addMagnet(magnet,new File(root,"magnet-download"),false);connect(restored,magnetHash,38429);
            waitFor(()->restored.snapshot().get(0).metadata,"magnet retrieves real metadata from peer");
            waitFor(()->restored.snapshot().get(0).finished,"magnet downloads the complete bundle");
            check(Arrays.equals(two,Files.readAllBytes(new File(root,"magnet-download/bundle/skip.bin").toPath())),"magnet bytes match original");
            restored.network(false);restored.pause(magnetHash,true);check(restored.snapshot().get(0).paused,"network gating does not override manual pause");
            restored.network(true);check(restored.snapshot().get(0).paused,"network reconnect preserves manual pause");
            System.out.println("ALL INTEGRATION CHECKS PASSED; libtorrent "+LibTorrent.version());
        } finally {if(engine!=null)engine.close();seed.stop();}
    }
}
